{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Vol Desk Data",
    "url": "http://localhost:7801",
    "widgets_json": {
      "vol_screener": {
        "name": "Vol Screener",
        "description": "Screen names by implied-vol criteria.",
        "endpoint": "/vol-screener",
        "type": "table",
        "w": 24,
        "h": 10,
        "params": [
          {
            "paramName": "ticker",
            "type": "ticker",
            "label": "Ticker"
          },
          {
            "paramName": "as_of",
            "type": "date",
            "label": "As of",
            "value": "$currentDate-1d"
          },
          {
            "paramName": "only_liquid",
            "type": "boolean",
            "label": "Liquid only",
            "value": "true"
          }
        ],
        "staleTime": 900000
      },
      "vix_history": {
        "name": "VIX History",
        "description": "Daily CBOE VIX closes with returns.",
        "endpoint": "/vix-history",
        "type": "table",
        "w": 20,
        "h": 9,
        "params": [
          {
            "paramName": "window",
            "type": "number",
            "label": "Window",
            "value": "30",
            "min": "5",
            "max": "365"
          }
        ],
        "data": {
          "table": {
            "columnsDefs": [
              {
                "field": "date",
                "headerName": "Date",
                "cellDataType": "dateString"
              },
              {
                "field": "close",
                "headerName": "Close",
                "cellDataType": "number"
              },
              {
                "field": "return_pct",
                "headerName": "Return %",
                "cellDataType": "number",
                "formatterFn": "percent",
                "renderFn": "greenRed",
                "renderFnParams": {
                  "actionType": "groupBy",
                  "groupBy": {
                    "paramName": "return_pct"
                  }
                }
              }
            ]
          }
        },
        "staleTime": 900000
      },
      "vol_commentary": {
        "name": "Vol Commentary",
        "description": "Morning volatility commentary.",
        "endpoint": "/vol-commentary",
        "type": "markdown",
        "w": 12,
        "h": 8,
        "params": [
          {
            "paramName": "desk",
            "type": "text",
            "label": "Desk",
            "options": [
              {
                "value": "Index",
                "label": "Index"
              },
              {
                "value": "Single Stock",
                "label": "Single Stock"
              }
            ],
            "value": "Index"
          }
        ],
        "staleTime": 900000
      }
    },
    "apps_json": [
      {
        "name": "Vol Param Cockpit",
        "description": "Screen, history, and commentary filters.",
        "tabs": [
          {
            "tab_id": "screen",
            "name": "Screen",
            "layout": [
              {
                "i": "vol_screener",
                "x": 0,
                "y": 0,
                "w": 24,
                "h": 10
              },
              {
                "i": "vol_commentary",
                "x": 24,
                "y": 0,
                "w": 12,
                "h": 8
              }
            ]
          },
          {
            "tab_id": "history",
            "name": "History",
            "layout": [
              {
                "i": "vix_history",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          }
        ]
      }
    ]
  }
}

